    """Return true only for the exact live process generation in the marker."""
    if expected_ticks is None:
        return False
    try:
        if os.name == "nt":
            handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, int(pid))
            alive = False
            if handle:
